mapper.select:
select k.chunk_id, k.doc_id, k.chunk_index, k.content, k.content_hash, k.page_no, k.clause_no, k.char_start, k.char_end, k.create_by, k.create_time, k.update_by, k.update_time, k.remark, d.doc_name as doc_name, d.doc_type as doc_type,
(case when k.content like concat('%', #{kw}, '%') or k.clause_no like concat('%', #{kw}, '%') then 1 else 0 end)
as hit_count from jc_kb_chunk k left join jc_kb_document d on d.doc_id = k.doc_id where k.del_flag = '0' and d.del_flag = '0' and d.status = '已入库' and (d.expire_date is null or d.expire_date >= curdate()) and (
k.content like concat('%', #{kw}, '%') or k.clause_no like concat('%', #{kw}, '%')
)
and d.category_id = #{categoryId}
order by hit_count desc, k.doc_id, k.chunk_index limit #{limit}
